public class Christie
  {


  public static void main(String[]args) throws IOException
     {

      Scanner Sf = new Scanner(new File("christie.dat"));
      int T = Sf.nextInt();
      for(int i=1; i<=T; i=i+1)
         {
            int A=Sf.nextInt();
