               {
                  String St = ""+x;
                  int Sum = 0;
                  for(int y=0; y<St.length();y++)
                     {
                        String Sub = St.substring(y,y+1);
                        int Digit = Integer.parseInt(Sub);
                        Sum+=Digit*Digit;
                     }
                  boolean cool=false;
                  for(int q=1; q<=1000000;q++)   
